const deriveWsRole = (m) => {
  for (const role of Object.keys(WS_ROLE_PRESETS)) {
    const p = WS_ROLE_PRESETS[role];
    if (WS_PERMISSIONS.every(({ key }) => !!m?.[key] === !!p[key])) return role;
  }
  return "custom";
};

