  el.style.lineHeight = "1.4";
  const lines = (text || "").split("\n");
  if (runs && runs.length) el.innerHTML = wbRunsHtml(runs.length === 1 && !runs[0].t ? [{ ...runs[0], t: " " }] : runs);
