const wbShapePoints = (type, w, h) =>
  type === "diamond" ? `${w / 2},1 ${w - 1},${h / 2} ${w / 2},${h - 1} 1,${h / 2}`
  : `${w / 2},1 ${w - 1},${h - 1} 1,${h - 1}`; // triangle

