      width: "100%", height: "100%", background: "transparent", border: "none", outline: "none", resize: "none",
      fontFamily: FONT, fontSize, fontWeight: d.bold ? 700 : (it.type === "sticky" ? 500 : 400), lineHeight: 1.4,
