      const logos = [...(profile.logos || []).filter(l => l.key !== "primary"),
                     { key: "primary", label: "Primary", url: r.url, name: r.name, format: r.type || "" }];
      setProfile(pr => ({ ...pr, logos, logo_url: r.url }));
      await supabase.from("brand_profile")
